import{_ as t,l as m,o,c as d,v as e,p as s,x as r,d as l,i,S as A}from"./chunks/framework.InCnrqk-.js";const u=JSON.parse('{"title":"Command R / R+","description":"","frontmatter":{"title":"Command R / R+","date":"2026-09-07T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/cohere-command-r.md","filePath":"llm/cohere-command-r.md","lastUpdated":1789023840000}'),R={name:"llm/cohere-command-r.md"};function c(h,a,p,E,C,B){const n=m("Mermaid");return o(),d("div",null,[a[1]||(a[1]=e('<h1 id="command-r-r" tabindex="-1">Command R / R+ <a class="header-anchor" href="#command-r-r" aria-label="Permalink to &quot;Command R / R+&quot;">​</a></h1><div class="epigraph"><p>Command R 系列为生产级 RAG 与工具调用而训：能根据给定文档片段做带引用的生成，并能把多步工具串成工作流。</p><footer>—— Cohere，Command R / R+ 模型卡与文档，2024</footer></div><p>2024 年 3–4 月，Cohere 放出可下载的 <strong>Command R（约 35B）</strong> 与 <strong>Command R+（约 104B）</strong>，上下文 <strong>128k</strong>，许可 <strong>CC-BY-NC</strong> 加可接受使用政策。相对通用聊天模型，它们的公开卖点不是 MMLU 全面第一，而是<strong>带 grounding span 的引用生成</strong>与<strong>JSON 工具循环</strong>。多语底座与 Aya 23 的深度实验写在 <a href="/llm/command-r">Aya / Command-R+</a>；本篇只把 R 与 R+ 当作生产对象：模板即模型的一部分、单步对多步、08-2024 更新改了什么。Cohere 没有为 R / R+ 发与 Aya 23 同等级的 arXiv，<strong>不要伪造论文号</strong>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>把检索片段糊进上下文，通用模型不一定会引用，也不一定在工具失败后改参数再试。企业 RAG 需要三件同时成立：窗口装得下多段结果、答句里能标出来源片段、工具协议稳定到可以进工作流。Command R 要把这三件写进后训练，而不是只靠系统提示「请列出资料来源」。R+ 的问题更进一步：单次 JSON 动作不够时，能否规划—调用—观察—再调用。</p><p>第二条约束是许可与部署。开放权重面向研究与非商用；商用走 Cohere API、Bedrock 等授权渠道。把 R+ 与 Apache 的 7B 写在同一句「开源可商用」里，会在法务上翻车。</p><h3 id="r-与-r-的分工不是「同一个-35b-放大」" tabindex="-1">R 与 R+ 的分工不是「同一个 35B 放大」 <a class="header-anchor" href="#r-与-r-的分工不是「同一个-35b-放大」" aria-label="Permalink to &quot;R 与 R+ 的分工不是「同一个 35B 放大」&quot;">​</a></h3><p>模型卡把 R 定位为可扩展生产档：延迟与吞吐优先的 RAG、较简单的工具。R+ 定位为复杂 RAG 与<strong>多步工具</strong>（一次生成动作列表，执行后再进入下一步）。二者都是优化过的解码器 Transformer、都训 23 种语言、都在约 10 种语言上评测——评测集小于训练集，未列入的语种不能当成同等产品覆盖。08-2024 权重在同样硬件上宣称更高吞吐、更低延迟，并加入可调安全模式；能力叙事仍是 RAG + 工具，不是换骨干。Command R 08-2024 的参数量是否仍精确为 35B，应以该快照模型卡为准，不要把 v01 的 35B 未经核对就写到所有别名上。</p><p><span class="marginnote">偏离官方 RAG / 工具提示模板，引用率与工具选择会掉。迁移到自建网关时，应先复现模板，再换检索器。这是后训练把格式写进条件分布，不是解码器里多了一层指针网络。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>Grounded generation：模型吃一份文档片段列表，生成时插入指向片段的引用。该行为由监督微调与偏好微调、加上<strong>必须遵守的提示模板</strong>训出。08-2024 起，文档写明模型可以在某些 RAG 流程里<strong>不强制引用</strong>、并对不可回答的问题拒绝，同时对系统消息与空白类非语义扰动更稳。工具使用：对话 + 可选 preamble + 工具列表 → 输出 JSON 动作。R 档官方材料强调对话式工具；R+ 明确 multi-step / agentic。检索器仍在模型外——引用保证溯源格式，不保证片段相关。</p><h3 id="_128k-是装文档的预算-不是免检索" tabindex="-1">128k 是装文档的预算，不是免检索 <a class="header-anchor" href="#_128k-是装文档的预算-不是免检索" aria-label="Permalink to &quot;128k 是装文档的预算，不是免检索&quot;">​</a></h3><p>128k 用来容纳多文档与长对话。注意力仍按实现二次增长；把整库塞进窗口会先打爆显存与预填充账单。企业侧仍应切块、重排，再把 top 片段交给 grounded 模板。Command 系列常与 Cohere Embed / Rerank 组管道，那是产品组合，不是 R+ 权重内部自带向量库。</p>',13)),(o(),s(A,null,{default:r(()=>[i(n,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20RET%5B%22%E6%A3%80%E7%B4%A2%E5%99%A8%20%2F%20Rerank%22%5D%20--%3E%20DOCS%5B%22%E6%96%87%E6%A1%A3%E7%89%87%E6%AE%B5%E5%88%97%E8%A1%A8%22%5D%0A%20%20DOCS%20--%3E%20TPL%5B%22%E5%AE%98%E6%96%B9%20grounded%20%E6%A8%A1%E6%9D%BF%22%5D%0A%20%20TPL%20--%3E%20R%5B%22Command%20R%20~35B%22%5D%0A%20%20TPL%20--%3E%20RP%5B%22Command%20R%2B%20~104B%22%5D%0A%20%20R%20--%3E%20CITE%5B%22%E5%B8%A6%20span%20%E7%9A%84%E5%BC%95%E7%94%A8%E7%94%9F%E6%88%90%22%5D%0A%20%20RP%20--%3E%20CITE%0A%20%20RP%20--%3E%20TOOL%5B%22%E5%A4%9A%E6%AD%A5%20JSON%20%E5%B7%A5%E5%85%B7%E5%BE%AA%E7%8E%AF%22%5D%0A%20%20R%20--%3E%20TOOL1%5B%22%E6%9B%B4%E7%AE%80%E5%8D%95%E7%9A%84%E5%8D%95%E6%AD%A5%E5%B7%A5%E5%85%B7%22%5D%0A%20%20TOOL%20--%3E%20ENV%5B%22%E6%89%A7%E8%A1%8C%E4%B8%8E%E8%A7%82%E5%AF%9F%22%5D%0A%20%20ENV%20--%3E%20RP%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=e('<p>词表、层数、是否 <a href="/llm/gqa">GQA</a> 的精确头数，R / R+ 模型卡没有全部写成定理；Aya 23 报告给过同族 8B/35B 的表，但把那张表原样当成 R+ 104B 的规格属于越级。实现以开源配置与 <code>transformers</code> 配置为准。上下文 128k 是模型卡写明的。</p><p><span class="marginnote">仓库组织名从 <code>CohereForAI</code> 迁到 <code>CohereLabs</code> 一类。下载时核对 <code>v01</code> 与 <code>08-2024</code> 后缀。API 别名 <code>command-r</code> 可能随退役改指向，自托管应钉检查点哈希。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>引用的机制是格式学习：高频训练「先读片段、再在答句里打 span」。检索错了，模型仍会礼貌地引用错 PDF——grounding ≠ 事实验证。多步工具的机制是对话状态机，与 <a href="/llm/function-calling">function calling</a> 相同：约束解码提高 JSON 合法率，环境超时与空结果仍会导致循环。R+ 为之做了专门后训练，所以比通用 70B 更愿意按协议走，不是 104B 自带沙箱。</p><p>多语机制是容量分配：23 语种预训练混合意味着这些语种上的切词与指令覆盖更密。10 语评测是验收子集。长尾语种能生成，不等于能上生产安全门槛。与 Aya 23 的关系：35B 的 Aya 23 由 Command R 继续微调而来，深度实验见专文；本篇不把 101 语种的 Aya 101 写成 R+ 的词表。</p><h3 id="_08-2024-改的是服务曲线与鲁棒性" tabindex="-1">08-2024 改的是服务曲线与鲁棒性 <a class="header-anchor" href="#_08-2024-改的是服务曲线与鲁棒性" aria-label="Permalink to &quot;08-2024 改的是服务曲线与鲁棒性&quot;">​</a></h3><p>官方数字：Command R 08-2024 相对前代约 <strong>50% 吞吐</strong>、约 <strong>20% 更低延迟</strong>，服务所需硬件大约减半。同时改进「是否该调用工具」的决策、系统消息遵循、结构化数据分析。这些是推理栈与后训练的增量，没有伴随新的公开架构论文。回归测试必须用同一版本号：3 月权重与 8 月权重的延迟、拒答、无引用 RAG 行为都不同。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>Command 不是参数量冠军：对照同期 Llama 3 70B，选型理由是引用与工具，不是全面知识支配。知识截止与幻觉仍在。CC-BY-NC 禁止把权重放进商用 SaaS（除非另行授权）。不要给 Command R / R+ 伪造 arXiv；可引用模型卡、官方文档，以及 Aya 23（arXiv:2405.15032）作为同族多语证据。</p><p>后续 Command A 等旗舰是新后训练，不写进本篇规格表。JSON 模式在网关里若改 schema，等于离开训练域。128k 在 GQA 下 KV 仍随长度线性涨，生产上要设硬上限。</p><p><span class="marginnote">「可执行无引用 RAG」是 08-2024 的能力，不是「可以不要检索」。没有片段时拒绝，比胡编更符合企业合规；把拒答当失败用例，会逼模型退回幻觉。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Command R（~35B，2024-03）与 Command R+（~104B，2024-04）是 128k 开放权重，针对带引用 RAG 与工具；许可 CC-BY-NC。</li><li>R 侧重可扩展 RAG 与较简单工具；R+ 侧重多步工具。08-2024 提升吞吐/延迟并加强系统消息与可拒绝。</li><li>引用与工具依赖官方模板；长窗口不替代检索质量。多语与 Aya 见 <a href="/llm/command-r">Aya / Command-R+</a>。</li><li>出处：Cohere Command R / R+ 模型卡与文档（含 08-2024）。无官方 R/R+ 技术报告编号；勿伪造。</li></ul>',13))])}const _=t(R,[["render",c]]);export{u as __pageData,_ as default};
